                'updated_at' => '2026-05-04 19:05:44',
            ],
            [
                'id' => 2,
                'title' => "Breach Notice Invoice",
                'slug' => "breach-notice-invoice",
                'content' => "<h1 id=\"how-to-issue-breach-notice-invoice\">How to Issue Breach Notice Invoice</h1><ul><li><p>StrataMaster → Accounting → Issue Invoice → Miscellaneous Invoice</p></li></ul><p><img src=\"/storage/knowledge-base-images/lsRHGm74PDt7ruKmvq2B43r7dVgi6BRvhpv8O2L2.png\" data-id=\"knowledge-base-images/lsRHGm74PDt7ruKmvq2B43r7dVgi6BRvhpv8O2L2.png\"></p><hr><h1 id=\"refer-to-manual-invoice-requisition-form\">Refer to ‘Manual Invoice Requisition’ Form</h1><p><img src=\"/storage/knowledge-base-images/yBl4B3mE8CZD9PwLsM4c42I5K6T39RRkJFNwusqb.png\" data-id=\"knowledge-base-images/yBl4B3mE8CZD9PwLsM4c42I5K6T39RRkJFNwusqb.png\"></p><hr><h1 id=\"enter-details-from-manual-invoice-requisition-form\">Enter Details from ‘Manual Invoice Requisition’ Form</h1><p><img src=\"/storage/knowledge-base-images/igQUqWsqn45gT0mPo2hfJyBoFmYpLvYEJVH5RBSf.png\" data-id=\"knowledge-base-images/igQUqWsqn45gT0mPo2hfJyBoFmYpLvYEJVH5RBSf.png\"></p><ul><li><p>For description, use the following format: <span data-color=\"red\" class=\"color\" style=\"--color: oklch(0.577 0.245 27.325); --dark-color: oklch(0.704 0.191 22.216)\">‘Lot xxx: Breach Administration Fee for xxxxxxxx’</span>. Maximum 10 words.</p></li><li><p>Due date is issue date +28 days.</p></li></ul><hr><h1 id=\"generate-the-invoice\">Generate the Invoice</h1><ul><li><p>Click ‘Mail’ button</p></li></ul><p><img src=\"/storage/knowledge-base-images/hl9PPGiMRYORwRqZ1jzSROpAIYZvlkVQef2FiZ3W.png\" data-id=\"knowledge-base-images/hl9PPGiMRYORwRqZ1jzSROpAIYZvlkVQef2FiZ3W.png\"></p><ul><li><p>Send the Breach Invoice to the requester (i.e. the OC Manager and/or OC Assistant)</p></li></ul><hr><h1 id=\"charge-quantity-management-fee\">Charge Quantity Management Fee</h1><p><img src=\"/storage/knowledge-base-images/sXTl2LMJfPED5zvQJnAkXNiwUCPsklj8srgx8ii6.png\" data-id=\"knowledge-base-images/sXTl2LMJfPED5zvQJnAkXNiwUCPsklj8srgx8ii6.png\"></p><ul><li><p>When all details are entered, click <img src=\"/storage/knowledge-base-images/GAxtSZmwD9zwwZ1MazxpuwIfXo1Cz2b86q0zyRgV.png\" data-id=\"knowledge-base-images/GAxtSZmwD9zwwZ1MazxpuwIfXo1Cz2b86q0zyRgV.png\"> , and remember to save it by clicking <img src=\"/storage/knowledge-base-images/tO9orndwoQ5QW815fM67pvJIaVRBibVcALMUGcob.png\" data-id=\"knowledge-base-images/tO9orndwoQ5QW815fM67pvJIaVRBibVcALMUGcob.png\"></p></li></ul>",
                'toc' => [['id' => "how-to-issue-breach-notice-invoice", 'text' => "How to Issue Breach Notice Invoice", 'level' => "H1"], ['id' => "refer-to-manual-invoice-requisition-form", 'text' => "Refer to ‘Manual Invoice Requisition’ Form", 'level' => "H1"], ['id' => "enter-details-from-manual-invoice-requisition-form", 'text' => "Enter Details from ‘Manual Invoice Requisition’ Form", 'level' => "H1"], ['id' => "generate-the-invoice", 'text' => "Generate the Invoice", 'level' => "H1"], ['id' => "charge-quantity-management-fee", 'text' => "Charge Quantity Management Fee", 'level' => "H1"]],
